namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 sealed class Generators {
  Dictionary<string,List<string>> calls=new Dictionary<string,List<string>>{{"ctr_run_initfuncs",new List<string>()}};
  Obj constants=new Obj();Dictionary<string,Obj> enums=new Dictionary<string,Obj>();Dictionary<int,string> irqs=new Dictionary<int,string>();
  List<string> strings=new List<string>(),pins=new List<string>();List<string[]> encoders=new List<string[]>();Dictionary<string,string[]> commands=new Dictionary<string,string[]>();
  Dictionary<string,int> ids=new Dictionary<string,int>{{"identify_response offset=%u data=%.*s",0},{"identify offset=%u count=%c",1}};
  Dictionary<string,string> messages=new Dictionary<string,string>{{"identify_response","identify_response offset=%u data=%.*s"},{"identify","identify offset=%u count=%c"}};
  Dictionary<string,int> parameterSets=new Dictionary<string,int>();string led="",button="";bool encodedIds=true;
  static string[] Parts(string s,int max=0)=>max==0?Regex.Split(s.Trim(),@"\s+"):Regex.Split(s.Trim(),@"\s+",RegexOptions.None).Take(max).ToArray();
  static string Tail(string s,int count){for(int i=0;i<count;i++){var m=Regex.Match(s,@"^\S+\s*");s=s.Substring(m.Length);}return s;}
  static string Quoted(string s)=>s.Trim().Trim('"');
  public void Parse(string text){foreach(var line in text.Split(new[]{'\n','\0'},StringSplitOptions.RemoveEmptyEntries)){string s=line.Trim();if(s=="")continue;var p=Parts(s);switch(p[0]){
   case "_DECL_CALLLIST":if(!calls.ContainsKey(p[1]))calls[p[1]]=new List<string>();calls[p[1]].Add(p[2]);break;
   case "_DECL_STATIC_STR":string st=Tail(s,1);if(!strings.Contains(st))strings.Add(st);break;
   case "DECL_ENUMERATION":case "DECL_ENUMERATION_RANGE":if(!enums.ContainsKey(p[1]))enums[p[1]]=new Obj();object value=p[0].EndsWith("RANGE")?(object)new object[]{U.Number(p[3]),U.Number(p[4])}:U.Number(p[3]);if(enums[p[1]].ContainsKey(p[2])&&Json.Write(enums[p[1]][p[2]])!=Json.Write(value))throw new Exception("Enumeration conflict");enums[p[1]][p[2]]=value;break;
   case "DECL_CONSTANT":case "DECL_CONSTANT_STR":object cv=p[0].EndsWith("STR")?(object)Quoted(Tail(s,2)):U.Number(p[2]);if(constants.ContainsKey(p[1])&&Json.Write(constants[p[1]])!=Json.Write(cv))throw new Exception("Constant conflict");constants[p[1]]=cv;break;
   case "DECL_INITIAL_PINS":pins=Quoted(Tail(s,1)).Split(',').Select(v=>v.Trim()).Where(v=>v!="").ToList();if(pins.Count>0)constants["INITIAL_PINS"]=string.Join(",",pins);break;
   case "DECL_ARMCM_IRQ":int irq=(int)U.Number(p[2]);if(irqs.ContainsKey(irq)&&irqs[irq]!=p[1])throw new Exception("IRQ conflict");irqs[irq]=p[1];break;
   case "DECL_COMMAND_FLAGS":if(commands.ContainsKey(p[3]))throw new Exception("Command conflict");commands[p[3]]=new[]{p[1],p[2],p[3]};messages[p[3]]=Tail(s,3);break;
   case "_DECL_ENCODER":messages[p[1]]=Tail(s,1);encoders.Add(new[]{p[1],Tail(s,1)});break;
   case "_DECL_OUTPUT":encoders.Add(new[]{(string)null,Tail(s,1)});break;
   case "DECL_LED_PIN":led=Quoted(Tail(s,1));break;
   case "DECL_BUTTON":button=Quoted(Tail(s,1));break;
   default:throw new Exception("Unknown build-time command: "+p[0]);
  }}}
  int Pin(string pin,bool katapult){if(!enums.ContainsKey("pin"))throw new Exception("Missing pin enumeration");if(katapult&&constants.Any(c=>c.Key.StartsWith("RESERVE_PINS",StringComparison.OrdinalIgnoreCase)&&Convert.ToString(c.Value).Split(',').Contains(pin)))throw new Exception("Reserved pin: "+pin);foreach(var e in enums["pin"]){if(e.Value is object[] range){var m=Regex.Match(e.Key,@"^(.*?)(\d+)$");if(m.Success&&pin.StartsWith(m.Groups[1].Value)&&int.TryParse(pin.Substring(m.Groups[1].Length),out int n)){int start=int.Parse(m.Groups[2].Value),count=Convert.ToInt32(range[1]);if(n>=start&&n<start+count)return Convert.ToInt32(range[0])+n-start;}}else if(e.Key==pin)return Convert.ToInt32(e.Value);}throw new Exception("Unknown pin: "+pin);}
  static int MsgId(int id){int first=id<128?id:(id>>7)|128;int v=first&127;if((first&96)==96)v|=-32;if(id>=128)v=(v<<7)|(id&127);return v;}
  string Parser(int id,string message,bool command,bool output,bool minSize){string[] types;if(output)types=Regex.Matches(message,@"%%|%\.\*s|%\*s|%h[ui]|%[uics]").Cast<Match>().Select(m=>m.Value).Where(s=>s!="%%").ToArray();else types=Parts(message).Skip(1).Select(x=>x.Substring(x.IndexOf('=')+1)).ToArray();var mapping=new Dictionary<string,string>{{"%u","PT_uint32"},{"%i","PT_int32"},{"%hu","PT_uint16"},{"%hi","PT_int16"},{"%c","PT_byte"},{"%s","PT_string"},{"%.*s","PT_progmem_buffer"},{"%*s","PT_buffer"}};var pts=types.Select(t=>mapping[t]).ToArray();string key=string.Join(", ",pts),param="0";if(pts.Length>0){if(!parameterSets.ContainsKey(key))parameterSets[key]=parameterSets.Count;param="command_parameters"+parameterSets[key];}var b=new StringBuilder();b.Append((encodedIds?".encoded_msgid=":".msg_id=")+id+", .num_params="+pts.Length+", .param_types="+param+",");if(command)b.Append(".num_args="+(pts.Length+pts.Count(x=>x=="PT_buffer"||x=="PT_progmem_buffer")));else{int size=pts.Sum(t=>t=="PT_byte"?2:t=="PT_uint16"||t=="PT_int16"?3:t=="PT_uint32"||t=="PT_int32"?5:64)+5+(id>=128?2:1);b.Append(".max_size="+Math.Min(64,size));if(minSize)b.Append(", .min_size="+Math.Min(64,5+(id>=128?2:1)+pts.Length));}return b.ToString();}
  public string Generate(KConfig config,string project,string outdir,string toolVersion){bool katapult=project=="katapult";var b=new StringBuilder("/* Generated by the C# Klipper builder (GPLv3). */\n#include <stdint.h>\n#include \"board/irq.h\"\n#include \"board/pgm.h\"\n#include \"compiler.h\"\n#include \"initial_pins.h\"\n");if(!katapult)b.AppendLine("#include \"command.h\"");
   foreach(var call in calls){b.AppendLine("void "+call.Key+"(void) {");foreach(string f in call.Value){if(call.Key=="ctr_run_taskfuncs")b.AppendLine("irq_poll();");b.AppendLine("extern void "+f+"(void); "+f+"();");}if(call.Key=="ctr_run_taskfuncs")b.AppendLine("irq_poll();");b.AppendLine("}");}
   if(!katapult){b.AppendLine("uint8_t __always_inline ctr_lookup_static_string(const char *str) {");for(int i=0;i<strings.Count;i++)b.AppendLine("if (__builtin_strcmp(str, \""+strings[i]+"\") == 0) return "+(i+2)+";");b.AppendLine("return 0xff; }");if(!enums.ContainsKey("static_string_id"))enums["static_string_id"]=new Obj();for(int i=0;i<strings.Count;i++)enums["static_string_id"][strings[i]]=i+2;}
   b.AppendLine("const struct initial_pin_s initial_pins[] PROGMEM = {");foreach(var p in pins){bool low=p.StartsWith("!");b.AppendLine("{"+Pin(low?p.Substring(1).Trim():p,katapult)+", "+(low?"0":"IP_OUT_HIGH")+"},");}b.AppendLine("};\nconst int initial_pins_size PROGMEM = ARRAY_SIZE(initial_pins);");
   if(irqs.ContainsKey(-15)){b.AppendLine("extern void DefaultHandler(void); extern uint32_t _stack_end;");foreach(var f in irqs.Values.Distinct())b.AppendLine("extern void "+f+"(void);");b.AppendLine("const void *VectorTable[] __visible __section(\".vector_table\") = { &_stack_end,");for(int i=-15;i<=irqs.Keys.Max();i++)b.AppendLine((irqs.ContainsKey(i)?irqs[i]:"DefaultHandler")+",");b.AppendLine("};");}
   if(katapult){int lh=led!=""&&!led.StartsWith("!")?1:0;string lp=led.TrimStart('!').Trim();b.AppendLine("uint32_t led_gpio="+(lp==""?0:Pin(lp,true))+", led_gpio_high="+lh+";");int pull=button.StartsWith("^")?1:button.StartsWith("~")?-1:0;string bp=button.TrimStart('^','~');int high=bp!=""&&!bp.StartsWith("!")?1:0;bp=bp.TrimStart('!').Trim();b.AppendLine("int32_t button_gpio="+(bp==""?0:Pin(bp,true))+", button_high="+high+", button_pullup="+pull+";");return b.ToString();}
   encodedIds=File.ReadAllText(Path.Combine(config.Source,"src/command.h")).Contains("encoded_msgid");int next=1;foreach(var msg in commands.Keys.Select(k=>messages[k]).Concat(encoders.Select(e=>e[1])))if(!ids.ContainsKey(msg))ids[msg]=++next;if(next>=(encodedIds?16384:128))throw new Exception("Too many protocol message IDs");bool min=File.ReadAllText(Path.Combine(config.Source,"src/command.h")).Contains("min_size");StringBuilder body=new StringBuilder(),lookup=new StringBuilder(),outputs=new StringBuilder();var seen=new HashSet<int>();foreach(var enc in encoders){int id=ids[enc[1]];if(!seen.Add(id))continue;body.AppendLine("const struct command_encoder command_encoder_"+id+" PROGMEM = {"+Parser(id,enc[1],false,enc[0]==null,min)+"};");(enc[0]==null?outputs:lookup).AppendLine("if (__builtin_strcmp(str, \""+enc[1]+"\") == 0) return &command_encoder_"+id+";");}
   body.AppendLine("const __always_inline struct command_encoder *ctr_lookup_encoder(const char *str) {"+lookup+"return NULL;}\nconst __always_inline struct command_encoder *ctr_lookup_output(const char *str) {"+outputs+"return NULL;}");foreach(var f in commands.Values.Select(c=>c[0]).Distinct().OrderBy(x=>x))body.AppendLine("extern void "+f+"(uint32_t*);");var byId=commands.ToDictionary(c=>ids[messages[c.Key]],c=>c.Value);body.AppendLine("const struct command_parser command_index[] PROGMEM = {");for(int id=0;id<=byId.Keys.Max();id++){if(!byId.ContainsKey(id)){body.AppendLine("{},");continue;}var c=byId[id];body.AppendLine("{"+Parser(id,messages[c[2]],true,false,min)+", .flags="+c[1]+", .func="+c[0]+"},");}body.AppendLine("};\nconst "+(encodedIds?"uint16_t":"uint8_t")+" command_index_size PROGMEM = ARRAY_SIZE(command_index);");foreach(var pt in parameterSets.OrderBy(p=>p.Value))b.AppendLine("static const uint8_t command_parameters"+pt.Value+"[] PROGMEM = {"+pt.Key+"};");b.Append(body);
   Obj commandDict=new Obj(),responseDict=new Obj(),outputDict=new Obj();foreach(var pair in ids){string name=Parts(pair.Key)[0];var dest=commands.ContainsKey(name)?commandDict:messages.ContainsKey(name)?responseDict:outputDict;dest[pair.Key]=MsgId(pair.Value);}var dict=new Obj{{"enumerations",enums},{"config",constants},{"commands",commandDict},{"responses",responseDict},{"version",config.Version},{"build_versions",toolVersion},{"app","Klipper"},{"license","GNU GPLv3"},{"kconfig",config.ConfigText()}};if(outputDict.Count>0)dict["output"]=outputDict;
   string json=Json.Write(dict);File.WriteAllText(Path.Combine(outdir,"klipper.dict"),json,new UTF8Encoding(false));byte[] zipped=U.Zlib(Encoding.UTF8.GetBytes(json));b.AppendLine("const uint8_t command_identify_data[] PROGMEM = {"+string.Join(",",zipped.Select(v=>"0x"+v.ToString("x2")))+"};\nconst uint32_t command_identify_size PROGMEM = ARRAY_SIZE(command_identify_data);");return b.ToString();
  }
  public static void Stage2(byte[] input,string output){if(input.Length>252)throw new Exception("Stage2 too large");byte[] data=new byte[256];Array.Copy(input,data,input.Length);uint crc=0xffffffff;for(int i=0;i<252;i++){crc^=(uint)data[i]<<24;for(int bit=0;bit<8;bit++)crc=(crc<<1)^((crc&0x80000000)!=0?0x04c11db7u:0);}U.Put32(data,252,crc);File.WriteAllText(output,".cpu cortex-m0plus\n.thumb\n.section .boot2, \"ax\"\n.byte "+string.Join(",",data.Select(v=>"0x"+v.ToString("x2")))+"\n",new UTF8Encoding(false));}
  public static byte[] KatapultBinary(byte[] data,KConfig k,string output){long max=U.Number(k.Get("LAUNCH_APP_ADDRESS"))-U.Number(k.Get("FLASH_START"));if(data.Length>max)throw new Exception("Katapult exceeds bootloader reserved space");if(k.Get("BOARD_DIRECTORY")=="lpc176x"){uint total=0;for(int i=0;i<7;i++)total+=U.V32(data,i*4);U.Put32(data,28,unchecked(0-total));}int length=data.Length;var padded=data.Concat(Enumerable.Repeat((byte)255,8-length%8)).ToArray();File.WriteAllText(output,"#include <stdint.h>\n#include \"deployer.h\"\nconst uint8_t deployer_canboot_binary[]={"+string.Join(",",padded.Select(v=>"0x"+v.ToString("x2")))+"};\nconst uint32_t deployer_canboot_binary_size="+length+";\n",new UTF8Encoding(false));return data;}
 }
 static class Elf {
  public static IEnumerable<uint[]> Segments(byte[] elf){if(elf.Length<52||elf[0]!=127||elf[1]!=69||elf[2]!=76||elf[3]!=70||elf[4]!=1||elf[5]!=1||BitConverter.ToUInt16(elf,18)!=40)throw new Exception("Not ARM ELF32");int off=(int)U.V32(elf,28),size=BitConverter.ToUInt16(elf,42),count=BitConverter.ToUInt16(elf,44);for(int i=0;i<count;i++){int p=off+i*size;var seg=Enumerable.Range(0,8).Select(n=>U.V32(elf,p+n*4)).ToArray();if(seg[0]==1&&seg[4]>0){if((long)seg[1]+seg[4]>elf.Length)throw new Exception("Invalid ELF range");yield return seg;}}}
  public static object Verify(string elf,string bin,uint start){byte[] e=File.ReadAllBytes(elf),b=File.ReadAllBytes(bin);var s=Segments(e).ToList();if(s.Count==0||s.Min(x=>x[3])!=start)throw new Exception("ELF load address mismatch");foreach(var r in s){long offset=(long)r[3]-start;if(offset<0||offset+r[4]>b.Length)throw new Exception("BIN load range mismatch");for(int i=0;i<r[4];i++)if(b[offset+i]!=e[r[1]+i])throw new Exception("BIN and ELF differ");}return new{load_address=start,load_segments=s.Count,binary_matches_elf=true};}
  public static void Uf2(string elf,string output,uint family){var e=File.ReadAllBytes(elf);var pages=new SortedDictionary<uint,byte[]>();foreach(var s in Segments(e)){if(s[3]<0x10000000||(ulong)s[3]+s[4]>0x15000000)throw new Exception("Invalid UF2 address");for(uint i=0;i<s[4];i++){uint address=s[3]+i,page=address&~255u;if(!pages.ContainsKey(page))pages[page]=new byte[256];pages[page][address&255]=e[s[1]+i];}}using(var file=File.Create(output)){uint idx=0;foreach(var page in pages){file.Write(Block(page.Key,page.Value,idx++,(uint)pages.Count,family),0,512);}}}
  public static byte[] Block(uint address,byte[] payload,uint index,uint count,uint family){byte[] b=new byte[512];uint[] header={0x0a324655,0x9e5d5157,0x2000,address,256,index,count,family};for(int i=0;i<8;i++)U.Put32(b,i*4,header[i]);Array.Copy(payload,0,b,32,payload.Length);U.Put32(b,508,0x0ab16f30);return b;}
 }
